199: function journeyError(context: { json: (body: unknown, status?: number) => Response }, error: unknown, validationMessage: string) {
200:   if (error instanceof ExperienceFailure) {
201:     return context.json({
202:       code: error.code,
203:       message: error.message,
204:       retryable: error.retryable,
205:       operationId: error.operationId,
206:     }, error.status as 400);
207:   }
208:   if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
209:     return context.json({ code: "WORKFLOW_CONFLICT", message: error.message, retryable: false }, 409);
210:   }
211:   if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: validationMessage, retryable: true }, 400);
212:   throw error;
213: }

