367:   private async claim(actionId: string, payload: object, expectedRevision: number): Promise<Claimed> {
368:     const loaded = await this.store.load();
369:     const hash = payloadHash(payload);
370:     const existing = loaded.state.actions.find((action) => action.id === actionId);
371:     if (existing) {
372:       if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
