45:     if (affected.has(dependent.id) && dependent.status === "APPROVED") dependent.status = "STALE";
46:   }
47:   for (const approval of next.approvals) {
48:     if ((approval.sectionId === sectionId || affected.has(approval.sectionId)) && approval.staleReason === null) {
